def parse_duration(s):
    """
    Converts a duration string (e.g., '1h30m', '45s', '2h5s') into a total number of seconds (int).

    Args:
        s: The duration string.

    Returns:
        The total number of seconds as an integer.
    """
    total_seconds = 0
    parts = s.split()
    for part in parts:
        if part.endswith('s'):
            value = int(part[:-1])
            if part == 's':
                total_seconds += value
            else:
                total_seconds += value * 60
        elif part.endswith('m'):
            value = int(part[:-1])
            total_seconds += value * 60 * 60
        elif part.endswith('h'):
            value = int(part[:-1])
            total_seconds += value * 60 * 60 * 60
        else:
            try:
                total_seconds += int(part)
            except ValueError:
                pass  # Ignore invalid parts

    return total_seconds
