def is_valid_ipv4(s):
    """
    Checks if a given string is a valid IPv4 address.

    Args:
        s: The string to check.

    Returns:
        True if the string is a valid IPv4 address, False otherwise.
    """
    try:
        parts = s.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            if not part.isdigit():
                return False
            num = int(part)
            if num < 0 or num > 255:
                return False
            if len(part) > 1 and part[0] == '0':
                return False
        return True
    except:
        return False
